# Supplementary Table S3 (JS / Claude 2026-10-24): the prospective (longitudinal) analysis behind fig_supp_prospective:
# does BMI at a visit predict the change in height Z / head-circumference Z to the next visit, in carriers < 18 y?
# Compiles, per outcome x group: age-varying test (p that the BMI effect differs from 0 at any age; mixed GAM, 05/07),
# the all-ages constant coefficient with SE, t and p (11), and the fixed age-window coefficients with SE, t and p
# (height: lmer windows < 8, 8-13, 13-18 y from 05; head circumference: 2-5 and 5-18 y from 07). Children and interval counts.
# Inputs: age_varying_beta.csv, age_window_coefficients.csv, hc_prospective_age_varying.csv, hc_prospective_windows.csv,
# supp_prospective_all_ages.csv (all regenerated by 01 -> 05 -> 07 -> 11 after QC).
# Outputs: supp_table_S3_prospective.csv, sheet "S3 prospective" added to supp_tables_bmi_effects.xlsx, section appended to supp_tables_bmi_effects.md
suppressPackageStartupMessages({ library(data.table); library(openxlsx) })
HERE <- "C:/Users/Jonathan Sebat/sebatlab Dropbox/Manuscripts/PGC_joint_submission/Molly/CNV_ASD_growth_analysis/CNV_growth_trajectories"
pfx <- function(p) ifelse(is.na(p), "", ifelse(p < 1e-16, "< 1e-16", ifelse(p < 0.001, sprintf("%.1e", p), ifelse(p < 0.01, sprintf("%.3f", p), sprintf("%.2f", p)))))
GROUPS <- c("16p11.2 del", "16p11.2 dup", "22q11.2 del", "22q11.2 dup", "Pooled")
# age-varying p and counts
h <- fread(file.path(HERE, "age_varying_beta.csv"), encoding = "UTF-8")[outcome == "HEIGHT" & grepl("^Prospective", model), .(p_age_varying = p_smooth[1]), by = .(locus)][, outcome := "Height"]
hc <- fread(file.path(HERE, "hc_prospective_age_varying.csv"))[, .(p_age_varying = p[1], children = children[1], intervals = intervals[1]), by = locus][, outcome := "Head circumference"]
# all-ages constant coefficient (11)
cst <- fread(file.path(HERE, "supp_prospective_all_ages.csv"))
# height counts come from 11's ivh (not written); recompute from the helper
source(file.path(HERE, "00_helpers.R")); ivh <- intervals(long_data("HEIGHT"))
nh <- rbind(ivh[, .(children = uniqueN(id), intervals = .N), by = .(locus = as.character(locus))], ivh[, .(locus = "Pooled", children = uniqueN(id), intervals = .N)])[, outcome := "Height"]
av <- rbind(merge(h, nh, by = c("locus", "outcome"), all.x = TRUE), hc, fill = TRUE)
base <- merge(av, cst, by = c("locus", "outcome"), all = TRUE)
base[, t_all := beta_all / se_all]
# windows
wh <- fread(file.path(HERE, "age_window_coefficients.csv"))[outcome == "HEIGHT" & model == "P", .(locus, outcome = "Height", window = win, est, se, p, persons, rows)]
wc <- fread(file.path(HERE, "hc_prospective_windows.csv"))[, .(locus, outcome = "Head circumference", window = w, est, se, p, persons = children, rows = intervals)]
W <- rbind(wh, wc)[, t := est / se]
S3 <- rbind(base[, .(outcome, group = locus, term = "all ages (constant BMI coefficient)", children, intervals, est = beta_all, se = se_all, t = t_all, p = p_all, p_age_varying)],
            W[, .(outcome, group = locus, term = paste0("window ", window), children = persons, intervals = rows, est, se, t, p, p_age_varying = NA_real_)], fill = TRUE)
S3[, outcome := factor(outcome, c("Height", "Head circumference"))][, group := factor(group, GROUPS)]
S3 <- S3[!is.na(group)]; setorder(S3, outcome, group, term)
fwrite(S3, file.path(HERE, "supp_table_S3_prospective.csv"))
F3 <- S3[, .(Outcome = as.character(outcome), Group = as.character(group), Term = term, Children = children, Intervals = intervals,
             `Effect per SD of BMI Z (SE)` = ifelse(is.na(est), "", sprintf("%+.3f (%.3f)", est, se)), t = ifelse(is.na(t), "", sprintf("%.2f", t)), p = pfx(p), `Age-varying p` = pfx(p_age_varying))]
note <- c("Table S3: prospective effect of BMI on subsequent growth in CNV carriers < 18 y (fig_supp_prospective). Outcome: change in height Z (WHO) or head-circumference Z (UK90) from one visit to the next, per 1 SD of BMI Z at the first visit, adjusted for Z at the visit, interval length, sex, locus (pooled) and cohort, with a child random intercept. Height: cleaned longitudinal visits of SVIP, Searchlight and Cardiff (intervals >= 0.5 y; 05_age_varying.R). Head circumference: full SVIP v10 series + Cardiff, G2MH, SSC (07_hc_trajectories.R). Plausibility QC (00_qc_growth.R) applied to the genomatrix and the SVIP v10 series. 22q11.2 dup has too few repeat measures and is not shown in the figure.",
          "Age-varying p: mixed GAM with s(age, by = BMI); p that the BMI effect differs from 0 at any age. All ages: the same model with a single constant BMI coefficient (effect, SE, t = effect / SE, p). Windows: linear mixed model (lmer) with BMI x age-window terms for height (< 8, 8-13, 13-18 y) and GAM-based windows for head circumference (2-5, 5-18 y); t = estimate / SE.")
wb <- loadWorkbook(file.path(HERE, "supp_tables_bmi_effects.xlsx"))
if ("S3 prospective" %in% names(wb)) removeWorksheet(wb, "S3 prospective"); addWorksheet(wb, "S3 prospective"); writeData(wb, "S3 prospective", F3)
setColWidths(wb, "S3 prospective", cols = 1:9, widths = c(18, 14, 36, 10, 10, 26, 8, 10, 14)); addStyle(wb, "S3 prospective", createStyle(textDecoration = "bold"), rows = 1, cols = 1:9)
nt <- read.xlsx(wb, "notes"); nt <- rbind(nt, data.frame(Note = note)); removeWorksheet(wb, "notes"); addWorksheet(wb, "notes"); writeData(wb, "notes", nt); setColWidths(wb, "notes", cols = 1, widths = 160)
saveWorkbook(wb, file.path(HERE, "supp_tables_bmi_effects.xlsx"), overwrite = TRUE)
mdt <- function(x, title) { h <- names(x); c(sprintf("## %s", title), "", paste0("| ", paste(h, collapse = " | "), " |"), paste0("|", paste(rep("---", length(h)), collapse = "|"), "|"), apply(x, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |")), "") }
md <- readLines(file.path(HERE, "supp_tables_bmi_effects.md")); md <- md[!grepl("^## Table S3", md) | FALSE]
cut <- grep("^## Table S3", md); if (length(cut)) md <- md[seq_len(cut[1] - 1)]
writeLines(c(md, paste0("- ", note), "", mdt(F3, "Table S3. Prospective effect of BMI on subsequent growth (carriers < 18 y)")), file.path(HERE, "supp_tables_bmi_effects.md"))
print(F3, nrows = 100); cat("S3 written\n")
